from .clock import age_hours

SLA_HOURS = {"high": 4, "normal": 24, "low": 72}

def is_overdue(ticket, now):
    limit = SLA_HOURS.get(ticket.get("severity", "normal"), 24)
    return age_hours(ticket["created_at"], now) >= limit

