class Notifier:
    def __init__(self):
        self.sent = set()
        self.messages = []

    def send_once(self, ticket_id, event):
        key = (ticket_id, event)
        if key in self.sent:
            return False
        self.sent.add(key)
        self.messages.append({"ticket_id": ticket_id, "event": event})
        return True

