from .repository import TicketRepository
from .routing import choose_ticket
from .notifications import Notifier

class SupportService:
    def __init__(self, tickets, notifier=None):
        self.repository = TicketRepository(tickets)
        self.notifier = notifier if notifier is not None else Notifier()

    def next_ticket(self, now):
        return choose_ticket(self.repository.all(), now)

    def close(self, ticket_id):
        changed = self.repository.close(ticket_id)
        if changed:
            self.notifier.send_once(ticket_id, "closed")
        return changed

